&lt;b&gt;&lt;i&gt;Le Manuel &lt;u&gt;Armes &amp; &#201;quipement&lt;/u&gt; pr&#233;sente un objet identique nomm&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Heaume-De-Compr&#233;hension.html&quot; title=&quot;Heaume de compr&#233;hension&quot;&gt;Heaume de Compr&#233;hension&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/td&gt;&lt;td style=&quot;height:30px&quot;&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
